const b=$json.body??$json;
const query=String(b.query??'').trim();
const slug=String(b.category_slug??'').trim();
const lat=Number(b.lat??32.6546),lon=Number(b.lon??51.6680);
const limit=Math.max(1,Math.min(100,Number(b.limit)||50));
const storeId=b.store_id==null||b.store_id===''?null:Number(b.store_id);
const errors=[];
if(!query&&!slug)errors.push('query or category_slug is required');
if(!slug&&!query)errors.push('query is required for category discovery');
if(!Number.isFinite(lat)||lat<25||lat>40)errors.push('lat must be between 25 and 40');
if(!Number.isFinite(lon)||lon<44||lon>64)errors.push('lon must be between 44 and 64');
if(storeId!==null&&(!Number.isInteger(storeId)||storeId<1))errors.push('store_id must be a positive integer');
if(errors.length)return[{json:{ok:false,statusCode:400,error:errors.join('; ')}}];
return[{json:{ok:true,query:query||slug,category_slug:slug||null,lat,lon,limit,store_id:storeId,source:'okala',requested_at:new Date().toISOString()}}];

const input=$('Validate Input').first().json;
const response=$json;
const status=Number(response.statusCode??200);
if(status>=400) return[{json:{ok:false,statusCode:status,error:'Okala category API returned HTTP '+status+'. If this is a bot-check/403/429, stop and retry later; this workflow does not bypass it.'}}];
const body=response.body??response;
const roots=body?.data?.categories??body?.data?.data?.categories??[];
const flat=[];
function walk(nodes){for(const n of (Array.isArray(nodes)?nodes:[])){flat.push(n);if(Array.isArray(n.children))walk(n.children)}}
walk(roots);
const norm=s=>String(s??'').replace(/[ي]/g,'ی').replace(/[ك]/g,'ک').replace(/[\u200c\s]+/g,' ').toLowerCase().trim();
let chosen=[];
if(input.category_slug){
 const found=flat.find(n=>String(n.latinName??'').toLowerCase()===input.category_slug.toLowerCase());
 if(found)chosen=[found];
 else return[{json:{ok:false,statusCode:422,error:'category_slug not found in categories available near this location',query:input.query}}];
}else{
 const tokens=norm(input.query).split(' ').filter(x=>x.length>1);
 const scored=flat.map(n=>{const name=norm(n.name),slug=norm(n.latinName);let score=0;for(const t of tokens){if(name.split(' ').includes(t)||slug.split('-').includes(t))score+=2;else if(name.includes(t)||slug.includes(t))score+=1;}return{n,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);
 if(!scored.length)return[{json:{ok:false,statusCode:422,error:'No matching category was found. Send category_slug from Okala categories or try a broader Persian category name.',query:input.query}}];
 const best=scored[0].score;
 chosen=scored.filter(x=>x.score===best).slice(0,2).map(x=>x.n);
}
return chosen.map(n=>({json:{...input,category_slug:n.latinName,category_name:n.name,category_id:n.id}}));

const input=$('Validate Input').first().json;
const results=$input.all();
const digits=s=>String(s??'').replace(/[۰-۹٠-٩]/g,c=>{const a='۰۱۲۳۴۵۶۷۸۹'.indexOf(c);return a>=0?String(a):String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))});
const toToman=v=>{const n=Number(digits(v));return Number.isFinite(n)&&n>0?Math.round(n/10):null};
const norm=s=>String(s??'').replace(/[ي]/g,'ی').replace(/[ك]/g,'ک').replace(/[\u200c\s]+/g,' ').toLowerCase().trim();
const tokens=norm(input.query).split(' ').filter(x=>x.length>1);
const seen=new Set(),rows=[],errors=[];
for(const item of results){
 const response=item.json??{},status=Number(response.statusCode??200);
 if(status>=400){errors.push('HTTP '+status);continue;}
 const body=response.body??response;
 for(const group of (body.data??[])){
  const store=group.store??{};
  for(const p of (group.products??[])){
   const name=String(p.name??'').trim();
   if(!name)continue;
   const id=String(p.id??p.productId??'');
   const sid=String(store.storeId??p.storeId??'');
   const key=sid+':'+id;
   if(seen.has(key))continue;
   seen.add(key);
   const score=tokens.filter(t=>norm(name).includes(t)).length;
   if(tokens.length&&score===0)continue;
   const pct=Number(p.discountPercent??0)||0;
   const final=toToman(p.okPrice);
   const regular=pct?toToman(p.price):final;
   rows.push({query:input.query,category_slug:body.category_slug??null,product_id:id||null,product_name:name,brand:p.brandName??p.brand??null,store_id:sid||null,store_name:store.storeName??p.storeName??null,price_toman:regular,final_price_toman:final,discount_percent:pct,in_stock:Boolean(p.hasQuantity??((Number(p.quantity)||0)>0))&&p.supplyStatus!==2,max_order:p.maxOrderLimit??null,product_url:id?'https://www.okala.com/product/'+id+'?storeId='+sid:null,source_url:'https://www.okala.com/',captured_at:new Date().toISOString()});
  }
 }
}
rows.sort((a,b)=>(b.discount_percent-a.discount_percent)||((a.final_price_toman??Infinity)-(b.final_price_toman??Infinity)));
const limited=rows.slice(0,input.limit);
if(!limited.length)return[{json:{ok:false,statusCode:422,error:errors.length?'Okala API failed: '+errors.join(', '):'No matching products returned. Try a category_slug or broader query.',query:input.query,category_count:results.length}}];
return[{json:{ok:true,count:limited.length,total_before_limit:rows.length,duplicate_count:seen.size-rows.length,query:input.query,lat:input.lat,lon:input.lon,rows:limited}}];
